//! Table metadata generated by `#[table]`.

use std::fmt;
use std::marker::PhantomData;

use hyve_core::HyveError;

use crate::value::{DbValue, SqlType, SqlValue, column_error};

/// A model stored in a table (`#[table("projects")]`).
pub trait Table: Sized + Send + 'static {
    /// The table name.
    const NAME: &'static str;
    /// The primary-key column.
    const PK: &'static str;
    /// Column names in field order.
    const COLUMNS: &'static [&'static str];
    /// Column types and nullability in field order.
    const TYPES: &'static [(SqlType, bool)];

    /// The field values in column order.
    fn values(&self) -> Vec<DbValue>;

    /// Builds the model from values in column order.
    fn from_values(values: Vec<DbValue>) -> Result<Self, HyveError>;
}

/// A typed column of `M` holding `T` (`Project::OWNER_ID`), for chaining
/// queries.
pub struct Column<M, T> {
    name: &'static str,
    _types: PhantomData<fn() -> (M, T)>,
}

impl<M, T> Column<M, T> {
    /// A column named `name`.
    pub const fn new(name: &'static str) -> Self {
        Column {
            name,
            _types: PhantomData,
        }
    }

    /// The column name.
    pub const fn name(&self) -> &'static str {
        self.name
    }
}

impl<M, T> Clone for Column<M, T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<M, T> Copy for Column<M, T> {}

impl<M, T> fmt::Debug for Column<M, T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Column({})", self.name)
    }
}

/// Decodes the next column value (used by `#[table]`'s `from_values`).
pub fn column_value<T: SqlValue>(
    values: &mut std::vec::IntoIter<DbValue>,
    table: &str,
    column: &str,
) -> Result<T, HyveError> {
    let v = values
        .next()
        .ok_or_else(|| column_error(table, column, "missing from the row".into()))?;
    T::from_db(v).map_err(|why| column_error(table, column, why))
}
